import{_ as t,o,c as a,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const c=JSON.parse('{"title":"Statement Download Agent","description":"","frontmatter":{"title":"Statement Download Agent"},"headers":[],"relativePath":"docs/tools/statement-agents.md","filePath":"docs/tools/statement-agents.md","lastUpdated":1794529254000}'),s={name:"docs/tools/statement-agents.md"};function r(i,e,d,l,p,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="statement-download-agent-beta" tabindex="-1">Statement Download Agent (Beta) <a class="header-anchor" href="#statement-download-agent-beta" aria-label="Permalink to &quot;Statement Download Agent (Beta)&quot;">​</a></h1><p>Add statements you have already downloaded, or let the Statement Download Agent collect them in the OrbySystems browser. You sign in to the bank yourself. The agent&#39;s job is downloading statements, not making payments or trades.</p><h2 id="get-statements-into-a-project" tabindex="-1">Get statements into a project <a class="header-anchor" href="#get-statements-into-a-project" aria-label="Permalink to &quot;Get statements into a project&quot;">​</a></h2><ol><li>Open the project&#39;s add-statements action and choose the <strong>Statement Download Agent (Beta)</strong>. Choose or enter your bank.</li><li>Sign in yourself in the OrbySystems browser, then choose <strong>I&#39;m signed in</strong> in the app. OrbySystems waits for this step before inspecting the signed-in page.</li><li>Use the known route to statements when available. Otherwise open the statements page yourself. If OrbySystems does not know the layout, download one statement the way you normally do so it can learn from that example locally.</li><li>Review the accounts, periods and any document-version choice offered. Choose the statements to download and import.</li></ol><p>OrbySystems uses what it has learned on this computer before asking you to demonstrate the page again. It checks downloaded statements against the account and period listed on the page. If the page changes or a file does not match, it asks for help rather than treating the file as a successful match. You can stop the operation.</p><p>A new or unsupported statement format may still need a parser before its records can be imported. Follow the app&#39;s prompt to <a href="/docs/tools/add-new-institution">request institution support</a>.</p><h2 id="review-supported-institutions" tabindex="-1">Review supported institutions <a class="header-anchor" href="#review-supported-institutions" aria-label="Permalink to &quot;Review supported institutions&quot;">​</a></h2><p><strong>Tools → Statement Download Agent → Supported institutions</strong> lists the available agents and their settings. Only one statement-agent operation runs at a time because they share the browser.</p><h2 id="share-an-improvement-if-you-choose" tabindex="-1">Share an improvement, if you choose <a class="header-anchor" href="#share-an-improvement-if-you-choose" aria-label="Permalink to &quot;Share an improvement, if you choose&quot;">​</a></h2><p>Learning from your example stays on your computer. The app can offer to share a privacy-protected copy of the page and learned steps. Read that copy before sending it; sharing is optional.</p><p>The tool&#39;s <strong>Add a new institution</strong> tab also provides a recording and review workflow for requesting an agent. Sign in before recording, demonstrate a statement download, then use <strong>Stop and save</strong> to review the prepared sample. Send it only after checking it contains nothing you want to keep private.</p>',11)])])}const u=t(s,[["render",r]]);export{c as __pageData,u as default};
